#!/usr/bin/env python3
"""Diagnostic parser for git worktree --porcelain with automated hygiene."""
import os
from pathlib import Path
import subprocess
import sys

def inspect_worktrees():
    cmd = ["git", "worktree", "list", "--porcelain"]
    res = subprocess.run(cmd, capture_output=True, text=True, check=True)

    worktrees = []
    cur = {}
    for line in res.stdout.splitlines():
        line = line.strip()
        if not line:
            if cur:
                worktrees.append(cur)
                cur = {}
            continue
        parts = line.split(" ", 1)
        k = parts[0]
        v = parts[1] if len(parts) > 1 else True
        if k == 'worktree':
            if cur:
                worktrees.append(cur)
                cur = {}
            cur['path'] = v
        elif k == 'HEAD':
            cur['head'] = v
        elif k == 'branch':
            cur['branch'] = v
        elif k == 'locked':
            cur['locked'] = True
            cur['lock_reason'] = v
        elif k == 'prunable':
            cur['prunable'] = v

    if cur:
        worktrees.append(cur)

    print(f"Found {len(worktrees)} active worktree registration(s):")
    for wt in worktrees:
        exists = Path(wt['path']).exists()
        print(f"  • Path: {wt['path']} (Exists: {exists}) | Branch: {wt.get('branch', 'DETACHED')}")
        if wt.get('locked'):
            print(f"    [LOCKED] Reason: {wt.get('lock_reason')}")

    # Prune stale metadata
    subprocess.run(["git", "worktree", "prune", "--verbose"], check=True)

if __name__ == '__main__':
    inspect_worktrees()

import os
from pathlib import Path
from typing import Dict, Optional

def inspect_smbios_dmi_tables(sysfs_root: str = "/sys/class/dmi/id") -> Dict[str, Optional[str]]:
    """Reads SMBIOS hardware information strictly through Linux read-only sysfs."""
    root = Path(sysfs_root)
    dmi_fields = {
        "bios_vendor": "bios_vendor",
        "bios_version": "bios_version",
        "bios_date": "bios_date",
        "board_vendor": "board_vendor",
        "board_name": "board_name",
        "product_uuid": "product_uuid",
        "sys_vendor": "sys_vendor",
    }
    results = {}
    for key, filename in dmi_fields.items():
        node = root / filename
        if node.exists() and os.access(node, os.R_OK):
            try:
                results[key] = node.read_text(encoding="utf-8").strip()
            except OSError:
                results[key] = None
        else:
            results[key] = None
    return results

if __name__ == "__main__":
    info = inspect_smbios_dmi_tables()
    print(f"SMBIOS BIOS Version: {info.get('bios_version', 'UNKNOWN')}")

import re
from typing import Dict, List, Any, Tuple

def parse_efibootmgr_verbose(output: str) -> Dict[str, Any]:
    """Parses efibootmgr verbose output strictly in read-only inspection mode."""
    boot_order = []
    boot_current = None
    entries: Dict[str, Dict[str, str]] = {}

    for line in output.splitlines():
        line = line.strip()
        if line.startswith("BootCurrent:"):
            boot_current = line.split(":", 1)[1].strip()
        elif line.startswith("BootOrder:"):
            raw_order = line.split(":", 1)[1].strip()
            boot_order = [item.strip() for item in raw_order.split(",") if item.strip()]
        elif re.match(r"^Boot[0-9A-Fa-f]{4}\*?", line):
            m = re.match(r"^Boot([0-9A-Fa-f]{4})(\*)?\s+(.*?)\t(.*)$", line)
            if m:
                entry_id, active, title, devpath = m.groups()
                entries[entry_id] = {
                    "active": bool(active),
                    "title": title.strip(),
                    "device_path": devpath.strip(),
                }

    return {
        "boot_current": boot_current,
        "boot_order": boot_order,
        "entries": entries,
    }

import os
from pathlib import Path
from typing import List, Dict, Any

def inspect_pci_option_roms(pci_sysfs_root: str = "/sys/bus/pci/devices") -> List[Dict[str, Any]]:
    """Inspects PCI expansion ROMs in read-only mode, verifying the 0xAA55 signature."""
    pci_dir = Path(pci_sysfs_root)
    rom_reports = []
    if not pci_dir.exists():
        return rom_reports

    for dev_path in sorted(pci_dir.glob("*")):
        rom_node = dev_path / "rom"
        if rom_node.exists() and os.access(rom_node, os.R_OK):
            try:
                with open(rom_node, "rb") as f:
                    header = f.read(2)
                    has_valid_sig = (header == b"\x55\xaa")
                    rom_reports.append({
                        "device_id": dev_path.name,
                        "rom_readable": True,
                        "has_valid_signature": has_valid_sig,
                    })
            except (PermissionError, OSError):
                continue
    return rom_reports
